fns.checkNameFile:
function checkNameFile(file) {
    var specialFilenameChars = /["\\/:*?<>|,]/;

    if (!file) {
        console.error("No file provided for validation.");
        return false;
    }

    // Check for invalid characters in the filename

    if (specialFilenameChars.test(file)) {
        Swal.fire({
            imageUrl: errorIconUrl,
            title: `<span class="lang_Invalid_file_name">ชื่อไฟล์ไม่ถูกต้อง</span>`,
            html: `<span class="lang_invalid_characters">ชื่อไฟล์มีอักขระที่ไม่ถูกต้อง</span> <span>(\\/:*?&lt;&gt;|,)</span>`,
            confirmButtonText: "<span data_th='ตกลง' data_en='OK'></span>",
        });
        changeDatalang();
        return false;
    }

    return true;
}

fns.handleFileUpload:
async function handleFileUpload(file, f) {
    const screenWidth = window.innerWidth;
    let sizeRatio = f == 42 ? 3 / 4 : null;

    var filecrop;

    if (f == 42) {
        cropperSettings = {
            aspectRatio: sizeRatio,
            minCropBoxWidth: 150,
            minCropBoxHeight: 200,
            modalWidth: 450,
            modalHeight: 300,
        };
        if (important_data.is_mobile == "Y") {
            const modalWidth = screenWidth * 0.9;
            const modalHeight = (modalWidth * 3) / 4 + 100;

            cropperSettings = {
                aspectRatio: 3 / 4,
                minCropBoxWidth: modalWidth * 0.5,
                minCropBoxHeight: modalWidth * 0.5 * (3 / 4),
                modalWidth: modalWidth,
                modalHeight: modalHeight,
            };
        }
        filecrop = await cropImage(file);
    } else {
        filecrop = file;
    }

    return filecrop;
}

fns.getParameterByName:
function getParameterByName(name, url = window.location.href) {
    name = name.replace(/[\[\]]/g, "\\$&");
    var regex = new RegExp("[?&]" + name + "(=([^&#]*)|&|#|$)"),
        results = regex.exec(url);
    if (!results) return null;
    if (!results[2]) return "";
    return decodeURIComponent(results[2].replace(/\+/g, "+"));
}

