function (event, id) {
    var app = getParameterByName("App");
    var files = document.getElementById("file_other_" + id + "").files;

    if (files.length > 0) {
        var isValid = checkTypeNameSizeFile(id, files[0]);

        if (!isValid) {
            return false; // Stop further execution
        }

        var reader = new FileReader();

        reader.readAsDataURL(files[0]);
        reader.onload = function () {
            let base64 = reader.result;
            let fileeditUp = files[0];
            let objectUrl = URL.createObjectURL(fileeditUp);

            let newLink;
            if (app == "Y" || app == "y") {
                FileOrtherbase64 = base64;
                newLink = `
                    <a id="tagaorther_${id}" onclick="sendmessage('${base64}')">
                        <p class="name-file namedoc" id="show_orther_file_name_${id}" value="${fileeditUp.name}">${fileeditUp.name}</p>
                    </a>`;
            } else {
                objectUrllink = objectUrl;
                newLink = `
                    <a id="tagaorther_${id}" href="${objectUrl}" target="_blank">
                        <p class="name-file namedoc" id="show_orther_file_name_${id}" value="${fileeditUp.name}">${fileeditUp.name}</p>
                    </a>`;
            }

            // 🟢 เขียน DOM ใหม่ให้ตรง format block-doc
            $("#divshow_file_name_" + id).html(`
                <div class="d-flex">
                    <div><img src="/assets/images/document.svg"></div>
