            // set ค่าอื่น ๆ
            $("#divshow_" + id).css("display", "flex");
            $("#divselect_" + id).css("display", "none");
            $("#hidden_current_file_new" + id).val("N");
            $("#hidden_file_up_" + id).prop("files", files);
        };
    }
